uvm = (q1*uvm.xy + vec2(1.0,-1.0)*q2*uvm.yx)*vec2(1.0,1.6) + vec2(.3,.5);
ret.xyz = max(ret.xyz, texture( sampler_fw_main,uvm).xyz*.9 - .01);

uvm = (_uv - vec2(.5,.5))*1.1;
uvm = (q3*uvm.xy + vec2(1.0,-1.0)*q4*uvm.yx)*vec2(1.0,1.6) + vec2(.5,.8);
ret.xyz = max(ret.xyz, texture( sampler_fw_main,uvm).xyz*.9 - .01);

uvm = (_uv - vec2(.5,.5))*1.5;
uvm = (q4*uvm.xy + vec2(1.0,-1.0)*q5*uvm.yx)*vec2(1.0,1.6) + vec2(.6,.4);
