comp:
shader_body
{

    vec3 base = texture(sampler_main, uv).xyz;
    vec2 d = texsize.zw*2.0;
    vec3 dx = ( ((texture(sampler_blur1, uv + vec2(1.0,0.0)*d).xyz * scale1) + bias1) - ((texture(sampler_blur1, uv-vec2(1.0,0.0)*d).xyz * scale1) + bias1) );
    vec3 dy = ( ((texture(sampler_blur1, uv + vec2(0.0,1.0)*d).xyz * scale1) + bias1) - ((texture(sampler_blur1, uv-vec2(0.0,1.0)*d).xyz * scale1) + bias1) );
    vec2 my_uv = uv + vec2(dx.y,dy.y)*0.05;
    float grad = length(my_uv-uv)*32.0;
    float emboss = (dx.y+dy.y)*4.0 + 0.5;

    vec2 uv_echo =  0.5 + (uv-0.5) * vec2(-1.0,1.0) + vec2(dx.y,dy.y)*0.05;
    vec3 bird = vec3(max( texture(sampler_main, my_uv).x, texture(sampler_main, uv_echo).x));
           bird = vec3(pow(bird, vec3(1.4))*pow(hue_shader, vec3(2.0)));

    vec3 bg = emboss*vec3(0.0,0.0,1.0) + vec3(2.0,3.0,0.0)*grad + vec3(1.0,0.0,0.0)*base.y - vec3(0.0,0.0,0.3);
           bg = bg*0.6*clamp(1.0 - bird.x*4.0, 0.0, 1.0);

    vec3 wave = ((texture(sampler_blur1, uv+vec2(dx.y,dy.y)*0.1).xyz * scale1) + bias1)*clamp(1.0-bird.x*0.0, 0.0, 1.0);

ret = bg + bird;
ret = vec3(mix(ret, vec3(1.0), vec3(wave.z*6.0*(1.0-bird*3.0))));




}
